    "description": "新华社基辅8月20日电（记者李东旭）乌克兰空军20日凌晨在社交媒体发文称，俄军对乌克兰发动新一轮弹道导弹袭击，俄军的弹道导弹正在向乌首都基辅市方向移动。 当天零时许，乌空军发文提醒称，多枚弹道导弹正在从切尔尼戈夫州和波尔塔瓦州向基辅市方向飞来。 之后，新华社记者听到基辅市响起多次强烈爆炸声，随后记者所在的第聂伯区电力供应出现短时间中断。此前，记者已听到基辅市响起两轮强烈的持续爆炸声。 截至发稿时，基辅市空袭预警尚未解除。",
    "content": "新华社基辅8月20日电（记者李东旭）乌克兰空军20日凌晨在社交媒体发文称，俄军对乌克兰发动新一轮弹道导弹袭击，俄军的弹道导弹正在向乌首都基辅市方向移动。 当天零时许，乌空军发文提醒称，多枚弹道导弹正在从切尔尼戈夫州和波尔塔瓦州向基辅市方向飞来。 之后，新华社记者听到基辅市响起多次强烈爆炸声，随后记者所在的第聂伯区电力供应出现短时间中断。此前，记者已听到基辅市响起两轮强烈的持续爆炸声。 截至发稿时，基辅市空袭预警尚未解除。"
