    "author": "刘亚南",
    "description": "8月19日在美国纽约拍摄的手机画面显示的是美国联邦政府债务总额突破40万亿美元。新华社记者 张凤国 摄 新华社纽约8月19日电（记者刘亚南）美国财政部19日发布的数据显示，美国联邦政府债务总额已突破40万亿美元。",
