    "content": "新华社华盛顿8月19日电（记者黄强 徐剑梅）美国总统特朗普19日在白宫对媒体表示，可能在“某个时候”恢复与伊朗的谈判，但伊朗必须彻底放弃核武器。 当被问及美国是否会重返谈判时，特朗普说：“也许在某个时候吧。但眼下，我认为局势非常好。”他随后说，“道理很简单，他们必须彻底放弃”，“伊朗绝不能拥有核武器”。 特朗普再次声称美国“拥有”并“完全控制”霍尔木兹海峡，并称伊朗“偶尔发射无人机确实会带来麻烦”。 特朗普18日在社交媒体上称，目前和未来不会与伊朗进行任何会谈或对话。此前，特朗普一直坚称美国同伊朗正在进行谈判，但遭…"
