    "content": "新华社伦敦8月19日电（记者张亚东）英国伦敦股市《金融时报》100种股票平均价格指数19日报收于10743.35点，较前一交易日上涨15.31点，涨幅为0.14%。欧洲三大股指当天涨跌不一。 当天伦敦股市成分股中位于涨幅前五位的个股分别为：贵金属生产商弗雷斯尼洛公司股价上涨7.83%，奋进矿业公司股价上涨7.49%，化学品企业克罗达国际公司股价上涨5.25%，嘉能可公司股价上涨5.24%，英美资源股价上涨4.80%。 当天伦敦股市成分股中位于跌幅前五位的个股分别为：金融衍生品交易服务IG集团股价下跌4.84%，医疗…"
