    "content": "19/08/2026 - 19:12 中国外长王毅周三开始对韩国进行为期两天的访问，背景是特朗普推动重启对朝外交，美韩军演宣布提前结束。王毅还称赞李在明政府成立后，中韩关系重回改善发展轨道... 据路透社说，中国外交部长王毅和韩国外交部长赵显于周三（8月19日）在首尔举行会谈，讨论了与朝鲜半岛有关的问题。 此次会晤是在首尔和华盛顿缩减联合军事演习规模之后举行的，美国总统唐纳德·特朗普表示，他希望恢复与朝鲜领导人金正恩的外交关系。 王毅表示，中国将继续在促进朝鲜半岛和平方面发挥建设性作用。中方一贯主张维护半岛和平稳定…"
