    "description": "新华社雅温得8月19日电（记者王泽 李玥）据喀麦隆国家广播电台19日报道，中非共和国西部边境地区一处金矿18日发生滑坡，初步统计已有逾百人遇难。 报道说，该矿区位于中非共和国西部的纳纳-曼贝雷省，与喀麦隆东部大区洛姆-杰雷姆州加鲁阿布莱交界。 当地媒体援引加鲁阿布莱市长的话报道说，截至19日早间，已有107人遇难。另据喀麦隆官方媒体报道，已确认有4名喀麦隆矿工遇难。 目前两国已开展互助救援工作并确认遇难者身份。",
    "content": "新华社雅温得8月19日电（记者王泽 李玥）据喀麦隆国家广播电台19日报道，中非共和国西部边境地区一处金矿18日发生滑坡，初步统计已有逾百人遇难。 报道说，该矿区位于中非共和国西部的纳纳-曼贝雷省，与喀麦隆东部大区洛姆-杰雷姆州加鲁阿布莱交界。 当地媒体援引加鲁阿布莱市长的话报道说，截至19日早间，已有107人遇难。另据喀麦隆官方媒体报道，已确认有4名喀麦隆矿工遇难。 目前两国已开展互助救援工作并确认遇难者身份。"
