    "title": "宁波的知与行：从藏书楼到博物馆的文脉流动",
    "link": "https://www.infzm.com/contents/328785",
    "pub_date": "2026-08-19 23:30:00",
    "author": "南方周末特约撰稿 梁潇",
    "description": "1997年，在鄞州区，宁波首座民办博物馆——宁波服装博物馆开幕，由宁波轻纺城股份有限公司出资筹建。如今，宁波79座正式备案的博物馆中，民办博物馆高达52座，占总数的65.8%，数量在全省各地级市中位列第一。当中企业办馆占多数。 南方周末特约撰稿 梁潇 责任编辑：杜茂林 一百多年前，在宁波镇海，桕墅方氏的子孙回到祠堂时，首先映入眼帘的是一副楹联，上联是：“科弟尚哉必忠孝廉节自任几端方可无惭宗祖”，下联是：“诗书贵矣但农工商贾各专一业便非不…",
    "content": "1997年，在鄞州区，宁波首座民办博物馆——宁波服装博物馆开幕，由宁波轻纺城股份有限公司出资筹建。如今，宁波79座正式备案的博物馆中，民办博物馆高达52座，占总数的65.8%，数量在全省各地级市中位列第一。当中企业办馆占多数。 博物馆已经代替宗祠，成为宁波人共同的精神坐标。通过博物馆，“异业同道”的信仰跳出了一家一姓的藩篱，却又让宁波的千家万户联结起来，如同一家姓，分享共同的价值追求。 南方周末特约撰稿 梁潇 责任编辑：杜茂林 一百多年前，在宁波镇海，桕墅方氏的子孙回到祠堂时，首先映入眼帘的是一副楹联，上联是：“科…"
