    "content": "感谢IT之家网友 竹本青 的线索投递！ IT之家 8 月 19 日消息，天马微电子 (TIANMA) 今日宣布，其高端 OLED 技术品牌“天马天工屏”的 2.0 发布会将于 8 月 26 日举行。 该发布会口号为“天工屏，定万象”，线下地点似乎是福建厦门 （原图分辨率过低导致无法完全确认） ，线上则将在当日 10:00~11:50 进行直播。 IT之家了解到，天马天工屏 2.0 将 以全新“原色好光”光谱材料带来护眼与通透上的全面升级 ， 着重提升 OLED 显示技术的健康度和舒适度 。"
