    "title": "宋韵雅礼续千年 杭州大运河畔上演古风集体婚礼",
    "link": "https://www.chinanews.com.cn/sh/2026/08-19/10680683.shtml",
    "pub_date": "2026-08-19 21:59:57",
    "author": "",
    "description": "中新网杭州8月19日电(张煜欢)七夕夜至，大运河畔古韵流转。19日，在杭州城北半山脚下，“爱在七夕·情定望宸”杭州市拱墅区第十一届大运河集体婚礼暨巧山乞巧民俗活动拉开帷幕。宋制婚典、乞巧游艺、非遗市集次第登场，千年巧山乞巧民俗借由一场沉浸式活动，让传统七夕文化走出典籍，化作可感可游的城市夜间浪漫。",
    "content": "中新网杭州8月19日电(张煜欢)七夕夜至，大运河畔古韵流转。19日，在杭州城北半山脚下，“爱在七夕·情定望宸”杭州市拱墅区第十一届大运河集体婚礼暨巧山乞巧民俗活动拉开帷幕。宋制婚典、乞巧游艺、非遗市集次第登场，千年巧山乞巧民俗借由一场沉浸式活动，让传统七夕文化走出典籍，化作可感可游的城市夜间浪漫。"
