    "description": "中新网拉萨8月19日电 (李林)19日，西藏自治区藏医院建院110周年发展成就新闻发布会在拉萨举行。发布会介绍，西藏自治区藏医院已发展成以藏医药医疗为主的集医疗、科研、教学、预防、保健和藏药制剂生产于一体的三级甲等藏医医院，全面进入了高质量发展新阶段。",
    "content": "中新网拉萨8月19日电 (李林)19日，西藏自治区藏医院建院110周年发展成就新闻发布会在拉萨举行。发布会介绍，西藏自治区藏医院已发展成以藏医药医疗为主的集医疗、科研、教学、预防、保健和藏药制剂生产于一体的三级甲等藏医医院，全面进入了高质量发展新阶段。"
