    "content": "新华社武汉8月19日电（记者罗兰）8月19日，第九个中国医师节。就在前几天，记者在湖北宜昌秭归县两河口镇两河村卫生室，又一次见到了王驹，他还是穿着白大褂，只不过从长袖换成了短袖。一米二八的身高，坐在卫生室的椅子上，双腿刚刚够到地面。 他戴着老花镜，左手轻敲键盘，右手挪动鼠标，正给患者开电子处方。身后的药柜前，常年摆着一张旧板凳，那是他用来取高处药品的“老伙计”。 两河村藏在鄂西大山里，从秭归县城开车过来，要在盘山路上绕近两个钟头。数千人“散”在山岭间，他是这里的一名乡村医生，今年59岁，已经干了38年。 “我从小身…"
