    "author": "赵伟宏,陈君清",
    "description": "新华社拉姆安拉8月19日电（记者赵伟宏）据巴勒斯坦通讯社报道，以色列军队19日在约旦河西岸和耶路撒冷多地开展军事行动，逮捕至少31名巴勒斯坦人，其中包括巴勒斯坦民族权力机构耶路撒冷事务部长阿什拉夫·阿瓦尔。 报道说，以方当天突袭阿瓦尔位于耶路撒冷老城阿克萨清真寺以南锡勒万区的住所并将其逮捕。阿瓦尔曾于今年1月被以色列当局禁止进入约旦河西岸。 巴民族权力机构当局发表声明说，逮捕阿瓦尔是以色列当局对耶路撒冷巴勒斯坦官员实施一系列限制措施的最…",
    "content": "新华社拉姆安拉8月19日电（记者赵伟宏）据巴勒斯坦通讯社报道，以色列军队19日在约旦河西岸和耶路撒冷多地开展军事行动，逮捕至少31名巴勒斯坦人，其中包括巴勒斯坦民族权力机构耶路撒冷事务部长阿什拉夫·阿瓦尔。 报道说，以方当天突袭阿瓦尔位于耶路撒冷老城阿克萨清真寺以南锡勒万区的住所并将其逮捕。阿瓦尔曾于今年1月被以色列当局禁止进入约旦河西岸。 巴民族权力机构当局发表声明说，逮捕阿瓦尔是以色列当局对耶路撒冷巴勒斯坦官员实施一系列限制措施的最新行动。 以军尚未对此发表声明。"
