    "content": "Position：高级 Rust 开发工程师（量化交易系统） Job Type: Full-Time ，Onsite-SG/HK （提供 EP ） PS： 核心职责是负责加密货币衍生品市场的自动化交易策略开发与低延迟交易系统的建设维护。日常需与交易员、量化研究员及基础设施工程师紧密配合，共同优化报价逻辑、交易执行与风控机制。最终目标是全面提升系统在高频环境下的稳定性，保障资产安全与交易顺畅。 Responsibilities 负责自动化交易策略及其系统开发维护，深度参与报价、对冲、仓位管理及风控逻辑的编码实现。需处…"
