    "content": "[分享]开源的摄影信息卡与水印排版工具 平时喜欢拍照，修完图发社交平台或者朋友圈时，总觉得市面上大多数加水印、做相框的 App 有点一言难尽： 手机端各种订阅制、广告，且没法直接在电脑端对整个输出文件夹一键批量跑完； 大多数边框工具千篇一律，要么就是生硬贴参数，稍微长一点的镜头名就文字重叠、溢出乱码； 很多工具在处理时会粗暴丢弃 ICC 色彩配置文件，导致精心调色的照片在不同设备上看发灰发色偏。 很多 skills 能力又被强大的大语言模型锁死（使用本地 cpu 算法+本地可运行模型），导致无法脱离 ai 工具的捆…"
